// Chunk splits a slice into chunks of at most n elements
func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		n = 1
	}

	if len(s) == 0 {
		return [][]T{}
	}

	chunks := make([][]T, 0)

	for i := 0; i < len(s); i += n {
		end := i + n
		if end > len(s) {
			end = len(s)
		}
		chunks = append(chunks, s[i:end])
	}

	return chunks
}

