// Flatten takes a slice of slices and returns a flattened slice containing
// all elements from the sub-slices in order.
func Flatten[T any](in [][]T) []T {
	if len(in) == 0 {
		return []T{}
	}

	// Calculate total length needed
	totalLen := 0
	for _, slice := range in {
		totalLen += len(slice)
	}

	// Create result slice with pre-allocated capacity
	result := make([]T, 0, totalLen)

	// Append all elements from sub-slices
	for _, slice := range in {
		result = append(result, slice...)
	}

	return result
}

