func Merge(in [][2]int) [][2]int {
	if len(in) == 0 {
		return nil
	}

	// Sort intervals by start point
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	var result [][2]int
	currentStart, currentEnd := in[0][0], in[0][1]

	for i := 1; i < len(in); i++ {
		start, end := in[i][0], in[i][1]

		if start <= currentEnd {
			// Overlapping intervals, merge them
			if end > currentEnd {
				currentEnd = end
			}
		} else {
			// Non-overlapping interval, add the previous merged interval
			result = append(result, [2]int{currentStart, currentEnd})
			currentStart, currentEnd = start, end
		}
	}

	// Add the last interval
	result = append(result, [2]int{currentStart, currentEnd})

	return result
}

