func Decode(s string) string {
	var result strings.Builder
	i := 0

	for i < len(s) {
		// Get the character
		char := s[i]
		i++

		// Extract the count
		countStr := ""
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			countStr += string(s[i])
			i++
		}

		// Convert count to integer
		count, _ := strconv.Atoi(countStr)

		// Append character 'count' times
		for j := 0; j < count; j++ {
			result.WriteByte(char)
		}
	}

	return result.String()
}

