func Caesar(s string, n int) string {
	result := make([]byte, len(s))

	for i, c := range s {
		if c >= 'a' && c <= 'z' {
			// Handle lowercase letters
			shifted := (int(c-'a') + n) % 26
			if shifted < 0 {
				shifted += 26
			}
			result[i] = byte(shifted + 'a')
		} else if c >= 'A' && c <= 'Z' {
			// Handle uppercase letters
			shifted := (int(c-'A') + n) % 26
			if shifted < 0 {
				shifted += 26
			}
			result[i] = byte(shifted + 'A')
		} else {
			// Leave non-letters unchanged
			result[i] = byte(c)
		}
	}

	return string(result)
}

