func TopK(s string, k int) []string {
	if s == "" || k <= 0 {
		return []string{}
	}

	words := strings.Fields(s)
	freq := make(map[string]int)

	for _, word := range words {
		freq[word]++
	}

	type freqWord struct {
		word  string
		count int
	}

	var freqWords []freqWord
	for word, count := range freq {
		freqWords = append(freqWords, freqWord{word, count})
	}

	sort.Slice(freqWords, func(i, j int) bool {
		if freqWords[i].count != freqWords[j].count {
			return freqWords[i].count > freqWords[j].count
		}
		return freqWords[i].word < freqWords[j].word
	})

	result := make([]string, 0, k)
	for i := 0; i < len(freqWords) && i < k; i++ {
		result = append(result, freqWords[i].word)
	}

	return result
}

