type Ring struct {
	data     []int
	capacity int
	size     int
	head     int
	tail     int
}

func NewRing(cap int) *Ring {
	return &Ring{
		data:     make([]int, cap),
		capacity: cap,
	}
}

func (r *Ring) Push(v int) {
	if r.size == r.capacity {
		r.head = (r.head + 1) % r.capacity
		r.size--
	}

	r.data[r.tail] = v
	r.tail = (r.tail + 1) % r.capacity
	r.size++
}

func (r *Ring) Items() []int {
	result := make([]int, r.size)
	for i := 0; i < r.size; i++ {
		idx := (r.head + i) % r.capacity
		result[i] = r.data[idx]
	}
	return result
}

