func Rotate(m [][]int) {
	n := len(m)

	// Transpose the matrix (swap rows with columns)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			m[i][j], m[j][i] = m[j][i], m[i][j]
		}
	}

	// Reverse each column to get the 90-degree clockwise rotation
	for i := 0; i < n/2; i++ {
		for j := 0; j < n; j++ {
			m[i][j], m[n-1-i][j] = m[n-1-i][j], m[i][j]
		}
	}
}

