func ParseQuery(q string) map[string][]string {
	result := make(map[string][]string)

	if q == "" {
		return result
	}

	pairs := strings.Split(q, "&")
	for _, pair := range pairs {
		if pair == "" {
			continue
		}

		idx := strings.Index(pair, "=")
		if idx == -1 {
			continue
		}

		key := pair[:idx]
		value := pair[idx+1:]

		if key == "" {
			continue
		}

		result[key] = append(result[key], value)
	}

	return result
}

