import "sync"

func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	var sum int
	var mu sync.Mutex
	var wg sync.WaitGroup

	wg.Add(workers)

	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for num := range jobs {
				mu.Lock()
				sum += num
				mu.Unlock()
			}
		}()
	}

	wg.Wait()
	return sum
}

