type UpperReader struct {
	reader io.Reader
	buf    []byte
	pos    int
	mu     sync.Mutex
}

func NewUpperReader(r io.Reader) *UpperReader {
	return &UpperReader{
		reader: r,
		buf:    make([]byte, 0),
		pos:    0,
	}
}

func (ur *UpperReader) Read(p []byte) (n int, err error) {
	ur.mu.Lock()
	defer ur.mu.Unlock()

	if ur.pos >= len(ur.buf) {
		// Refill buffer
		buf := make([]byte, 1024)
		n, err := ur.reader.Read(buf)
		if n == 0 {
			return 0, err
		}

		ur.buf = make([]byte, n)
		for i := 0; i < n; i++ {
			if buf[i] >= 'a' && buf[i] <= 'z' {
				ur.buf[i] = buf[i] - 'a' + 'A'
			} else {
				ur.buf[i] = buf[i]
			}
		}
		ur.pos = 0
	}

	// Copy from buffer to p
	n = copy(p, ur.buf[ur.pos:])
	ur.pos += n

	return n, err
}

