func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	if size <= 0 {
		return nil, io.ErrShortBuffer
	}

	var chunks [][]byte
	buffer := make([]byte, size)

	for {
		n, err := r.Read(buffer)
		if n > 0 {
			chunk := make([]byte, n)
			copy(chunk, buffer[:n])
			chunks = append(chunks, chunk)
		}
		if err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
	}

	return chunks, nil
}

