import "net/http"

func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	if len(mws) == 0 {
		return h
	}

	// Start with the innermost handler
	result := h

	// Apply middlewares from right to left (outermost to innermost)
	for i := len(mws) - 1; i >= 0; i-- {
		result = mws[i](result)
	}

	return result
}
